solution:
const people = [
  { name: "Hariom", dept: "IT" },
  { name: "Rahul", dept: "HR" },
  { name: "Amit", dept: "IT" },
  { name: "Priya", dept: "HR" }
]
const grouped = people.reduce((acc, p) => {
  acc[p.dept] = acc[p.dept] || []
  acc[p.dept].push(p.name)
  return acc
}, {})
return grouped
